# ---- occasions: editorial assignment (no companion guide for DC yet) ----
def occasions(name, cat=None, price=0):
    o=[]
    if cat=='Restaurants':
        if price>=4: o=['Romantic','Date night']
        elif price==3: o=['Date night','Romantic'] if name in ('Albi','Bresca','The Dabney','Kinship','Rose\'s Luxury','Little Pearl','Rooster & Owl','Oyster Oyster','Maydan','Le Diplomate','Rasika','Fiola Mare','Del Mar','Osteria Mozza DC') else ['Date night']
        elif price==2: o=['Casual','Date night']
        else: o=['Casual']
        if name in ('Maydan','Zaytinya','Jaleo','Oyamel','China Chilcano','Ambar','Desert 5','The Oak Room','Chai Pani','Maketto','Compass Rose','Founding Farmers','Le Diplomate','Old Ebbitt Grill','Cane','Dauphine\'s','Georgia Brown\'s','Shoto','Marcus DC','Dōgon','The Bazaar by José Andrés'): o=o+['Group']
    elif cat in ('Cafés',):
        o=['Date night','Casual'] if price>=2 else ['Casual']
        if 'Bar' in name or 'wine' in name.lower() or 'Wine' in name: o=['Date night']
    elif cat=='Speakeasies': o=['Date night','Late night']
    elif cat=='Bars':
        o=['Late night'] if price<=1 else ['Date night','Late night']
        if 'Brewing' in name or 'Beer' in name or name in ('ChurchKey','Bluejacket','Other Half DC','The Sovereign','Meridian Pint','The Brig','Dacha Beer Garden','Wunder Garten'): o=['Group','Casual']
        if name in ('Off the Record','Round Robin Bar','Quill','The Next Whisky Bar','Silver Lyan','Allegory','Dram & Grain','Barmini','Bar Charley','L\'Annexe'): o=['Romantic','Date night']
    elif cat=='Rooftops': o=['Date night','Group']
    elif cat=='Coffee': o=['Sweets','Brunch']
    elif cat=='Brunch': o=['Brunch']
    elif cat=='Off-beat': o=['Casual']
    elif cat=='Bakeries': o=['Sweets','Brunch']
    elif cat=='Dessert': o=['Sweets']
    elif cat=='Scene': o=['Group','Date night'] if price<=3 else ['Romantic','Group']
    elif cat=='Nightlife': o=['Late night','Group']
    return o

